  const sprites=[...roadside,...rivals.map(r=>({type:'rival',z:r.d-distance,r})),...cones.filter(c=>!c.hit).map(c=>({type:'cone',z:c.d-distance,c})),...gates.filter(g=>!g.passed).map(g=>({type:'gate',z:g.d-distance,g}))].filter(o=>o.z>(o.type==='rival'?24:0)&&o.z<view).sort((a,b)=>b.z-a.z);
