 function ui(){const rank=1+rivals.filter(r=>r.d>distance).length;const place=$('#race-place');if(place.dataset.rank!==String(rank)){place.dataset.rank=rank;place.innerHTML=`${rank}<span>/4</span>`;}const speedText=String(Math.round(speed*2));const gauge=$('#race-speedometer');gauge.setAttribute('aria-valuenow',speedText);gauge.classList.toggle('is-boosting',boost>0&&penalty===0);gauge.classList.toggle('is-slowed',penalty>0);$('#race-needle').style.transform=`rotate(${-125+Math.min(speed*2/280,1)*250}deg)`;const mode=phase==='countdown'?'READY':phase==='paused'?'PAUSED':penalty>0?'SLOWED':boost>0?'BOOST':'RACING';if($('#race-state').textContent!==mode)$('#race-state').textContent=mode;const note=penalty>0?penalty.toFixed(1)+'s TO RECOVER':boost>0?boost.toFixed(1)+'s REMAINING':'FULL THROTTLE';if($('#race-state-note').textContent!==note)$('#race-state-note').textContent=note;shell.querySelector('.race-stage').style.setProperty('--impact-opacity',String(impact));if($('#race-speed').textContent!==speedText)$('#race-speed').textContent=speedText;const distanceText=phase==='ready'?'START LINE':Math.round(distance/length*100)+'% OF CIRCUIT';if($('#race-distance').textContent!==distanceText)$('#race-distance').textContent=distanceText;$('#race-progress').style.width=(distance/length*100)+'%';$('#race-charge').style.width=(penalty>0?penalty/2.3*100:boost>0?100:charge*100)+'%';shell.querySelector('.race-boost').classList.toggle('is-slowed',penalty>0);const boostText=penalty>0?'RECOVERING SPEED':boost>0?'BOOST!':charge>.75?'RELEASE TO BOOST':'DRIFT TO CHARGE';if($('#race-boost-label').textContent!==boostText)$('#race-boost-label').textContent=boostText;const approaching=gates.find(g=>!g.passed&&g.d-distance<330);const callout=$('#race-callout');const message=noticeTime>0?notice:approaching?'PRODUCT GATES AHEAD — choose your lane':'';if(callout.textContent!==message)callout.textContent=message;callout.hidden=!message||phase==='ready'||phase==='done';}
